initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a set of Context Source Registration Subscriptions (CSRSs)
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration Subscription From File with Response Status Code set to 400     and
        Update Context Source Registration Subscription From File with Response Body containing the type 'problem_type=${ERROR_TYPE_BAD_REQUEST_DATA}' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'PATCH'
        Update Context Source Registration Subscription from file with subscription id set to '${subscription_id}' and subscription update fragment set to 'csourceSubscriptions/fragments/subscription-update-invalid-json-sample.json'
}
